138	// checkPackageNoImports verifies that no Go files in pkgPath import any of the forbidden imports.
139	func checkPackageNoImports(t *testing.T, pkgPath string, forbidden []string) {
140		t.Helper()
141		fset := token.NewFileSet()
142		err := filepath.WalkDir(pkgPath, func(path string, d fs.DirEntry, err error) error {
143			if err != nil {
144				return err
145			}
146			if d.IsDir() {
147				return nil
148			}
149			if filepath.Ext(path) != ".go" {
150				return nil
151			}
152			file, err := parser.ParseFile(fset, path, nil, parser.ImportsOnly)
153			if err != nil {
154				return err
155			}
156			for _, imp := range file.Imports {
157				importPath := strings.Trim(imp.Path.Value, `"`)
158				for _, forbid := range forbidden {
159					if importPath == forbid {
160						t.Errorf("%s imports %s (forbidden by CONTRACT-004)", path, forbid)
161					}
162				}
163			}
164			return nil
165		})
166		if err != nil && !strings.Contains(err.Error(), "no such file or directory") {
167			t.Fatalf("walk %s: %v", pkgPath, err)
168		}
169	}
