331	// findRepoRoot searches for the repository root by walking up the directory tree
332	// looking for go.mod.
333	func findRepoRoot(t *testing.T) string {
334		t.Helper()
335		cwd, err := filepath.Abs(".")
336		if err != nil {
337			t.Fatalf("get absolute path: %v", err)
338		}
339	
340		for {
341			if _, err := os.Stat(filepath.Join(cwd, "go.mod")); err == nil {
342				return cwd
343			}
344			parent := filepath.Dir(cwd)
345			if parent == cwd {
346				t.Fatal("could not find go.mod in any parent directory")
347			}
348			cwd = parent
