1	// Package session owns direct PTY process lifecycle and timed raw/input events.
2	//
3	// See internal/pty/doc.go for the governing ADR/SPIKE citations that authorize
4	// this package boundary.
5	package session
6	
7	import (
8		"context"
9		"errors"
10		"fmt"
11		"sync"
12		"time"
13	)
14	
15	// Size is a terminal rows/columns pair.
16	type Size struct {
17		Rows uint16
18		Cols uint16
19	}
20	
21	// OutputChunk is one timed raw PTY read.
22	type OutputChunk struct {
23		Seq       uint64
24		At        time.Time
25		TMS       int64
26		Offset    int64
27		Bytes     []byte
28		ReadError error
29		EOF       bool
30	}
31	
32	// EventKind identifies cassette-facing session events.
33	type EventKind string
34	
35	const (
36		EventOutput EventKind = "output"
37		EventInput  EventKind = "input"
38		EventResize EventKind = "resize"
39		EventSignal EventKind = "signal"
40		EventExit   EventKind = "exit"
41	)
42	
43	// Event is the narrow timed event shape consumed by follow-on cassette code.
44	type Event struct {
45		Seq    uint64
46		Kind   EventKind
47		At     time.Time
48		TMS    int64
49		Offset int64
50		Bytes  []byte
51		Key    Key
52		Size   Size
53		Signal string
54		Exit   *ExitStatus
55		Err    error
56	}
57	
58	// Key names common terminal inputs.
59	type Key string
60	
61	const (
62		KeyEnter     Key = "enter"
63		KeyTab       Key = "tab"
64		KeyEscape    Key = "escape"
65		KeyBackspace Key = "backspace"
66		KeyUp        Key = "up"
67		KeyDown      Key = "down"
68		KeyRight     Key = "right"
69		KeyLeft      Key = "left"
70	)
71	
72	// CtrlKey returns a letter control-key input such as Ctrl-C.
73	func CtrlKey(r rune) Key {
74		if r >= 'A' && r <= 'Z' {
75			r += 'a' - 'A'
76		}
77		return Key(fmt.Sprintf("ctrl-%c", r))
78	}
79	
80	// KeyBytes encodes a supported key as terminal input bytes.
81	func KeyBytes(k Key) ([]byte, error) {
82		switch k {
83		case KeyEnter:
84			return []byte{'\r'}, nil
85		case KeyTab:
86			return []byte{'\t'}, nil
87		case KeyEscape:
88			return []byte{0x1b}, nil
89		case KeyBackspace:
90			return []byte{0x7f}, nil
91		case KeyUp:
92			return []byte("\x1b[A"), nil
93		case KeyDown:
94			return []byte("\x1b[B"), nil
95		case KeyRight:
96			return []byte("\x1b[C"), nil
97		case KeyLeft:
98			return []byte("\x1b[D"), nil
99		}
100		var r rune
101		if _, err := fmt.Sscanf(string(k), "ctrl-%c", &r); err == nil {
102			if r >= 'A' && r <= 'Z' {
103				r += 'a' - 'A'
104			}
105			if r >= 'a' && r <= 'z' {
106				return []byte{byte(r - 'a' + 1)}, nil
107			}
108		}
109		return nil, fmt.Errorf("unsupported key %q", k)
110	}
111	
112	// Clock lets tests inject deterministic timestamps.
113	type Clock interface {
114		Now() time.Time
115	}
116	
117	type realClock struct{}
118	
119	func (realClock) Now() time.Time { return time.Now() }
120	
121	// Option configures Start.
122	type Option func(*Config)
123	
124	// Config controls session startup.
125	type Config struct {
126		Clock      Clock
127		Timeout    time.Duration
128		BufferSize int
129	}
130	
131	// WithClock injects a deterministic clock.
132	func WithClock(clock Clock) Option {
133		return func(cfg *Config) {
134			cfg.Clock = clock
135		}
136	}
137	
138	// WithTimeout applies a wall-clock timeout in addition to ctx cancellation.
139	func WithTimeout(timeout time.Duration) Option {
140		return func(cfg *Config) {
141			cfg.Timeout = timeout
142		}
143	}
144	
145	// WithBufferSize changes the raw read buffer size.
146	func WithBufferSize(size int) Option {
147		return func(cfg *Config) {
148			cfg.BufferSize = size
149		}
150	}
151	
152	func applyOptions(opts []Option) Config {
153		cfg := Config{Clock: realClock{}, BufferSize: 32 * 1024}
154		for _, opt := range opts {
155			opt(&cfg)
156		}
157		if cfg.Clock == nil {
158			cfg.Clock = realClock{}
159		}
160		if cfg.BufferSize <= 0 {
161			cfg.BufferSize = 32 * 1024
162		}
163		return cfg
164	}
165	
166	// ExitStatus describes process termination.
167	type ExitStatus struct {
168		Code     int
169		Signal   string
170		Exited   bool
171		Signaled bool
172		Err      error
173	}
174	
175	// Session is a running PTY-backed process.
176	type Session struct {
177		start  time.Time
178		clock  Clock
179		size   Size
180		cancel context.CancelFunc
181	
182		mu       sync.Mutex
183		seq      uint64
184		offset   int64
185		closed   bool
186		waitOnce sync.Once
187		waitDone chan struct{}
188		waitStat ExitStatus
189		readDone chan struct{}
190	
191		output       chan OutputChunk
192		events       chan Event
193		eventsMu     sync.Mutex
194		eventsClosed bool
195	
196		impl sessionImpl
197	}
198	
199	type sessionImpl interface {
200		write([]byte) (int, error)
201		resize(Size) error
202		close() error
203		kill() error
204		wait() ExitStatus
205	}
206	
207	var (
208		// ErrClosed is returned when writing to a closed session.
209		ErrClosed = errors.New("pty session closed")
210	)
211	
212	// Output returns timed raw PTY chunks. The channel closes after the read loop
213	// reaches EOF or Close/Kill tears the PTY down.
214	func (s *Session) Output() <-chan OutputChunk { return s.output }
215	
216	// Events returns timed input/output/resize/signal/exit events.
217	func (s *Session) Events() <-chan Event { return s.events }
218	
219	// Size returns the last requested terminal size.
220	func (s *Session) Size() Size {
221		s.mu.Lock()
222		defer s.mu.Unlock()
223		return s.size
224	}
225	
226	// SendBytes writes literal bytes to the PTY and records an input event.
227	func (s *Session) SendBytes(b []byte) error {
228		if len(b) == 0 {
229			return nil
230		}
231		if err := s.ensureOpen(); err != nil {
232			return err
233		}
234		if _, err := s.impl.write(b); err != nil {
235			return err
236		}
237		s.emit(Event{Kind: EventInput, Bytes: append([]byte(nil), b...)})
238		return nil
239	}
240	
241	// SendKey writes a named key sequence to the PTY and records an input event.
242	func (s *Session) SendKey(k Key) error {
243		b, err := KeyBytes(k)
244		if err != nil {
245			return err
246		}
247		if err := s.ensureOpen(); err != nil {
248			return err
249		}
250		if _, err := s.impl.write(b); err != nil {
251			return err
252		}
253		s.emit(Event{Kind: EventInput, Bytes: b, Key: k})
254		return nil
255	}
256	
257	// Resize changes the PTY size and records a resize event.
258	func (s *Session) Resize(size Size) error {
259		if err := validateSize(size); err != nil {
260			return err
261		}
262		if err := s.ensureOpen(); err != nil {
263			return err
264		}
265		if err := s.impl.resize(size); err != nil {
266			return err
267		}
268		s.mu.Lock()
269		s.size = size
270		s.mu.Unlock()
271		s.emit(Event{Kind: EventResize, Size: size})
272		return nil
273	}
274	
275	// Close cancels the session context and closes the PTY file descriptor.
276	func (s *Session) Close() error {
277		s.mu.Lock()
278		already := s.closed
279		s.closed = true
280		s.mu.Unlock()
281		if already {
282			return nil
283		}
284		if s.cancel != nil {
285			s.cancel()
286		}
287		return s.impl.close()
288	}
289	
290	// Kill terminates the process group where supported and records a signal event.
291	// If the process exits naturally at the same time, the signal event is best
292	// effort and may race with the exit event.
293	func (s *Session) Kill() error {
294		s.mu.Lock()
295		already := s.closed
296		s.closed = true
297		s.mu.Unlock()
298		if already {
299			return nil
300		}
301		if s.cancel != nil {
302			s.cancel()
303		}
304		s.emit(Event{Kind: EventSignal, Signal: "kill"})
305		return s.impl.kill()
306	}
307	
308	// Wait blocks until the process exits and returns its exit status.
309	func (s *Session) Wait() ExitStatus {
310		s.waitOnce.Do(func() {
311			s.waitStat = s.impl.wait()
312			s.mu.Lock()
313			s.closed = true
314			s.mu.Unlock()
315			s.emit(Event{Kind: EventExit, Exit: &s.waitStat})
316			close(s.waitDone)
317			if s.cancel != nil {
318				s.cancel()
319			}
320		})
321		<-s.waitDone
322		return s.waitStat
323	}
324	
325	func (s *Session) ensureOpen() error {
326		s.mu.Lock()
327		defer s.mu.Unlock()
328		if s.closed {
329			return ErrClosed
330		}
331		return nil
332	}
333	
334	func (s *Session) emit(ev Event) Event {
335		s.mu.Lock()
336		s.seq++
337		ev.Seq = s.seq
338		ev.At = s.clock.Now()
339		ev.TMS = ev.At.Sub(s.start).Milliseconds()
340		if ev.Kind == EventOutput {
341			ev.Offset = s.offset
342			s.offset += int64(len(ev.Bytes))
343		}
344		s.mu.Unlock()
345		s.eventsMu.Lock()
346		defer s.eventsMu.Unlock()
347		if s.eventsClosed {
348			return ev
349		}
350		select {
351		case s.events <- ev:
352		default:
353		}
354		return ev
355	}
356	
357	func (s *Session) closeEvents() {
358		s.eventsMu.Lock()
359		defer s.eventsMu.Unlock()
360		if s.eventsClosed {
361			return
362		}
363		s.eventsClosed = true
364		close(s.events)
365	}
366	
367	func (s *Session) emitOutput(b []byte, readErr error, eof bool) {
368		ev := Event{Kind: EventOutput, Bytes: append([]byte(nil), b...), Err: readErr}
369		ev = s.emit(ev)
370		chunk := OutputChunk{
371			Seq:       ev.Seq,
372			At:        ev.At,
373			TMS:       ev.TMS,
374			Offset:    ev.Offset,
375			Bytes:     ev.Bytes,
376			ReadError: readErr,
377			EOF:       eof,
378		}
379		s.output <- chunk
380	}
381	
382	func validateSize(size Size) error {
383		if size.Rows == 0 || size.Cols == 0 {
384			return fmt.Errorf("invalid terminal size rows=%d cols=%d", size.Rows, size.Cols)
385		}
386		return nil
387	}
388

