2	
3	package session
4	
5	import (
6		"context"
7		"errors"
8		"io"
9		"os"
10		"os/exec"
11		"syscall"
12		"time"
13	
14		"github.com/creack/pty"
15	)
16	
17	// Start launches command under a direct PTY with argv, workdir, env, and size.
18	// Cancellation is controlled by ctx and WithTimeout.
19	func Start(ctx context.Context, command string, args []string, workdir string, env []string, size Size, opts ...Option) (*Session, error) {
20		if command == "" {
21			return nil, errors.New("command is required")
22		}
23		if err := validateSize(size); err != nil {
24			return nil, err
25		}
26		cfg := applyOptions(opts)
27		if ctx == nil {
28			ctx = context.Background()
29		}
30		var timeoutCancel context.CancelFunc
31		if cfg.Timeout > 0 {
32			ctx, timeoutCancel = context.WithTimeout(ctx, cfg.Timeout)
33		}
34		runCtx, runCancel := context.WithCancel(ctx)
35		cancel := func() {
36			runCancel()
37			if timeoutCancel != nil {
38				timeoutCancel()
39			}
40		}
41		// #nosec G204 -- command and args are explicit PTY session API inputs;
42		// exec.Command does not invoke a shell.
43		cmd := exec.Command(command, args...)
44		cmd.Dir = workdir
45		if len(env) > 0 {
46			cmd.Env = append(os.Environ(), env...)
47		}
48	
49		ptmx, err := pty.StartWithSize(cmd, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
50		if err != nil {
51			cancel()
52			return nil, err
53		}
54	
55		s := &Session{
56			start:    cfg.Clock.Now(),
57			clock:    cfg.Clock,
58			size:     size,
59			cancel:   cancel,
60			output:   make(chan OutputChunk, 128),
61			events:   make(chan Event, 256),
62			waitDone: make(chan struct{}),
63			readDone: make(chan struct{}),
64		}
65		s.impl = &unixImpl{cmd: cmd, file: ptmx}
66	
67		go s.readLoop(ptmx, cfg.BufferSize)
68		go func() {
69			select {
70			case <-runCtx.Done():
71				select {
72				case <-s.waitDone:
73					return
74				default:
75				}
76				_ = s.Kill()
77			case <-s.waitDone:
78				return
79			}
80		}()
81		go func() {
82			<-s.waitDone
83			<-s.readDone
84			s.closeEvents()
85		}()
86		return s, nil
87	}
88	
89	func (s *Session) readLoop(r io.Reader, bufferSize int) {
90		defer close(s.readDone)
91		defer close(s.output)
92		buf := make([]byte, bufferSize)
93		for {
94			n, err := r.Read(buf)
95			if n > 0 {
96				s.emitOutput(buf[:n], nil, false)
97			}
98			if err != nil {
99				if errors.Is(err, io.EOF) || errors.Is(err, syscall.EIO) {
100					s.emitOutput(nil, nil, true)
101				} else {
102					s.emitOutput(nil, err, true)
103				}
104				return
105			}
106		}
107	}
108	
109	type unixImpl struct {
110		cmd  *exec.Cmd
111		file *os.File
112	}
113	
114	func (u *unixImpl) write(b []byte) (int, error) { return u.file.Write(b) }
115	
116	func (u *unixImpl) resize(size Size) error {
117		return pty.Setsize(u.file, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
118	}
119	
120	func (u *unixImpl) close() error { return u.file.Close() }
121	
122	func (u *unixImpl) kill() error {
123		if u.cmd.Process == nil {
124			return nil
125		}
126		pgid, err := syscall.Getpgid(u.cmd.Process.Pid)
127		if err == nil {
128			if killProcessGroup(pgid, syscall.SIGTERM) {
129				time.Sleep(100 * time.Millisecond)
130			}
131			_ = killProcessGroup(pgid, syscall.SIGKILL)
132			return nil
133		}
134		return u.cmd.Process.Kill()
135	}
136	
137	func killProcessGroup(pgid int, sig syscall.Signal) bool {
138		if pgid <= 0 {
139			return false
140		}
141		err := syscall.Kill(-pgid, sig)
142		return err == nil || errors.Is(err, syscall.ESRCH)
143	}
144	
145	func (u *unixImpl) wait() ExitStatus {
146		err := u.cmd.Wait()
147		if err == nil {
148			return ExitStatus{Code: 0, Exited: true}
149		}
150		status := ExitStatus{Code: -1, Err: err}
151		var exitErr *exec.ExitError
152		if errors.As(err, &exitErr) {
153			if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok {
154				status.Code = ws.ExitStatus()
155				status.Exited = ws.Exited()
156				status.Signaled = ws.Signaled()
157				if status.Signaled {
158					status.Signal = ws.Signal().String()
159				}
160			} else {
161				status.Code = exitErr.ExitCode()
162			}
163			return status
164		}
165		return status
166	}
