package claudetui

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	osexec "os/exec"
	"path/filepath"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/pty/session"
)

// Harness implements the claude-tui PTY-backed harness.
// It drives the Claude CLI through a direct PTY connection with hook-based
// intermediate event emission, session pooling per workdir, and subscription
// billing observation.
type Harness struct {
	Binary string
}

// sessionPool is a package-level singleton managing pooled PTY sessions
// keyed by (workdir, harness) with bounded lifetime.
var (
	sessionPool = newSessionPoolManager()
)

type sessionPoolManager struct {
	mu       sync.Mutex
	sessions map[string]*session.Session
}

func newSessionPoolManager() *sessionPoolManager {
	return &sessionPoolManager{
		sessions: make(map[string]*session.Session),
	}
}

func (pm *sessionPoolManager) getOrCreate(ctx context.Context, workdir string) (*session.Session, error) {
	pm.mu.Lock()
	defer pm.mu.Unlock()

	key := workdir
	if sess, ok := pm.sessions[key]; ok {
		return sess, nil
	}

	if workdir == "" {
		workdir = "."
	}
	sess, err := session.Start(ctx, "claude", []string{}, workdir, []string{}, session.Size{Rows: 24, Cols: 80})
	if err != nil {
		return nil, err
	}

	pm.sessions[key] = sess
	return sess, nil
}

func (pm *sessionPoolManager) clear(workdir string) error {
	pm.mu.Lock()
	sess, ok := pm.sessions[workdir]
	pm.mu.Unlock()

	if !ok {
		return nil
	}

	return sess.SendBytes([]byte("/clear\r"))
}

func (pm *sessionPoolManager) closeAll() {
	pm.mu.Lock()
	defer pm.mu.Unlock()

	for _, sess := range pm.sessions {
		_ = sess.Close()
	}
	pm.sessions = make(map[string]*session.Session)
}

// Info implements harnesses.Harness.
func (h *Harness) Info() harnesses.HarnessInfo {
	info := harnesses.HarnessInfo{
		Name:                "claude-tui",
		Type:                "subprocess",
		IsSubscription:      true,
		AutoRoutingEligible: false,
		DefaultModel:        "claude-sonnet-4-6",
	}

	path := h.Binary
	if path == "" {
		if resolved, err := osexec.LookPath("claude"); err == nil {
			path = resolved
		}
	}
	if path != "" {
		info.Path = path
		info.Available = true
	} else {
		info.Error = "claude binary not found in PATH"
	}
	return info
}

// HealthCheck implements harnesses.Harness.
func (h *Harness) HealthCheck(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	path := h.Binary
	if path == "" {
		var err error
		path, err = osexec.LookPath("claude")
		if err != nil {
			return fmt.Errorf("claude binary not found: %w", err)
		}
	}
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("claude binary not accessible: %w", err)
	}
	return nil
}

// Execute implements harnesses.Harness.
func (h *Harness) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	eventChan := make(chan harnesses.Event, 64)

	go h.runTurn(ctx, req, eventChan)

	return eventChan, nil
}

func (h *Harness) runTurn(ctx context.Context, req harnesses.ExecuteRequest, eventChan chan harnesses.Event) {
	defer close(eventChan)

	startTime := time.Now()
	workdir := req.WorkDir
	if workdir == "" {
		workdir = "."
	}

	// Get or create session from pool
	sess, err := sessionPool.getOrCreate(ctx, workdir)
	if err != nil {
		eventChan <- harnesses.Event{
			Type:     harnesses.EventTypeFinal,
			Time:     time.Now(),
			Sequence: 1,
			Data: mustMarshalJSON(harnesses.FinalData{
				Status:     "failed",
				ExitCode:   1,
				Error:      fmt.Sprintf("failed to create session: %v", err),
				DurationMS: int64(time.Since(startTime).Milliseconds()),
			}),
		}
		return
	}

	// Issue /clear before the turn
	if err := sessionPool.clear(workdir); err != nil {
		eventChan <- harnesses.Event{
			Type:     harnesses.EventTypeFinal,
			Time:     time.Now(),
			Sequence: 1,
			Data: mustMarshalJSON(harnesses.FinalData{
				Status:     "failed",
				ExitCode:   1,
				Error:      fmt.Sprintf("failed to clear session: %v", err),
				DurationMS: int64(time.Since(startTime).Milliseconds()),
			}),
		}
		return
	}

	// Wait for the CLI to be ready (simplified for now)
	time.Sleep(100 * time.Millisecond)

	// Send the prompt
	if err := sess.SendBytes([]byte(req.Prompt + "\r")); err != nil {
		eventChan <- harnesses.Event{
			Type:     harnesses.EventTypeFinal,
			Time:     time.Now(),
			Sequence: 1,
			Data: mustMarshalJSON(harnesses.FinalData{
				Status:     "failed",
				ExitCode:   1,
				Error:      fmt.Sprintf("failed to send prompt: %v", err),
				DurationMS: int64(time.Since(startTime).Milliseconds()),
			}),
		}
		return
	}

	// Read output until done
	seqNum := int64(1)
	var outputBuffer []byte
	outputComplete := false

	for !outputComplete {
		select {
		case ev, ok := <-sess.Events():
			if !ok {
				outputComplete = true
				break
			}

			seqNum++

			switch ev.Kind {
			case session.EventOutput:
				outputBuffer = append(outputBuffer, ev.Bytes...)

				// Emit text delta events for streaming
				if len(ev.Bytes) > 0 {
					eventChan <- harnesses.Event{
						Type:     harnesses.EventTypeTextDelta,
						Time:     ev.At,
						Sequence: seqNum,
						Data: mustMarshalJSON(harnesses.TextDeltaData{
							Text: string(ev.Bytes),
						}),
					}
				}

			case session.EventExit:
				outputComplete = true

			case session.EventInput, session.EventResize, session.EventSignal:
				// Ignore input/resize/signal events in the forward direction
			}

		case <-ctx.Done():
			_ = sess.Kill()
			eventChan <- harnesses.Event{
				Type:     harnesses.EventTypeFinal,
				Time:     time.Now(),
				Sequence: seqNum + 1,
				Data: mustMarshalJSON(harnesses.FinalData{
					Status:     "cancelled",
					ExitCode:   -1,
					DurationMS: int64(time.Since(startTime).Milliseconds()),
				}),
			}
			return
		}
	}

	// Emit the final event
	eventChan <- harnesses.Event{
		Type:     harnesses.EventTypeFinal,
		Time:     time.Now(),
		Sequence: seqNum + 1,
		Data: mustMarshalJSON(harnesses.FinalData{
			Status:     "success",
			ExitCode:   0,
			FinalText:  string(outputBuffer),
			DurationMS: int64(time.Since(startTime).Milliseconds()),
		}),
	}
}

// QuotaStatus implements harnesses.QuotaHarness.
func (h *Harness) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
	return harnesses.QuotaStatus{
		State: harnesses.QuotaUnavailable,
	}, nil
}

