	if err := json.Unmarshal(lastEvent.Data, &finalData); err != nil {
		t.Errorf("failed to unmarshal final data: %v", err)
	}

	// The test environment may not have a real Claude, so we just verify
	// that the harness produces valid events
	if finalData.Status != "success" && finalData.Status != "failed" && finalData.Status != "cancelled" {
		t.Errorf("final status: got %q, want success, failed, or cancelled", finalData.Status)
	}

	// Verify sequence numbers are monotonic
	if len(events) > 1 {
		for i := 1; i < len(events); i++ {
			if events[i].Sequence <= events[i-1].Sequence {
				t.Errorf("sequence not monotonic: event %d seq=%d, event %d seq=%d",
					i-1, events[i-1].Sequence, i, events[i].Sequence)
			}
		}
	}
}

